-- English 4 final module. Run seed_english4_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'english-4';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Literary Analysis Essay and Presentation$j$, $j${"prompt": "Write a literary analysis essay of at least 600 words on one work, author or movement from British or world literature studied in this course, and prepare a short presentation of its main ideas. Choose from: Beowulf, The Canterbury Tales, Everyman, a Shakespeare sonnet or tragedy, the King James Bible as literature, Paradise Lost, A Modest Proposal, The Pilgrim's Progress, a Romantic poem, Frankenstein, a Dickens novel, a Victorian poem, a poem by Yeats, Eliot or Owen, Animal Farm, Things Fall Apart or a work approved by your administrator. Write complete sentences and label each part. Proverbs 18:15 says, The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge.\n\nPart 1: Research Question and Thesis. State a clear question and a thesis that makes an arguable claim about the work.\nPart 2: Sources. List at least three sources (primary and secondary) with a note on how you judged each by authority, accuracy, currency and purpose. Use a consistent citation style.\nPart 3: The Essay. Write an introduction, at least three body paragraphs and a conclusion. Support each paragraph with quotations or specific details and explain your reasoning. Analyze at least two literary techniques and discuss the historical setting.\nPart 4: Scripture Connection. Connect a theme from the work to a passage of Scripture in the King James Version and explain the link.\nPart 5: Presentation Plan. Write a three part outline and a strong opening line for a three minute presentation, and list three delivery goals.\nPart 6: Revision. Revise your essay at least once after feedback from an adult, a peer or an online editing tool, and write a short note telling what you improved.", "rubric": "100 points. Part 1, research question and thesis: 10 points. Part 2, sources and citations: 10 points. Part 3, essay structure, evidence, technique analysis and context: 45 points. Part 4, Scripture connection: 7 points. Part 5, presentation plan: 10 points. Part 6, revision: 8 points. Grammar, conventions and academic voice: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Literary Analysis Essay and Presentation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: English 4$j$, $j${"questions": [{"q": "Beowulf is an example of:", "options": ["A Victorian novel", "An Old English epic", "A Renaissance sonnet", "A Middle English comedy"]}, {"q": "The Canterbury Tales is organized as:", "options": ["A frame narrative of pilgrims' stories", "A dictionary", "A single long speech", "A collection of letters"]}, {"q": "In Everyman, the only companion who goes with him to the end is:", "options": ["Fellowship", "Kindred", "Goods", "Good Deeds"]}, {"q": "A Shakespearean sonnet ends with:", "options": ["A refrain", "A caesura", "A stanza of eight lines", "A couplet"]}, {"q": "Iambic pentameter has:", "options": ["No pattern", "Five iambs per line", "Three beats per line", "Four lines per stanza"]}, {"q": "A tragic hero falls because of:", "options": ["A joke", "A flaw or bad choice", "Pure luck only", "A clear victory"]}, {"q": "The King James Bible was published in:", "options": ["1066", "1611", "1914", "1776"]}, {"q": "Satire uses humor and irony to:", "options": ["Praise kings", "Describe weather", "Criticize and aim at reform", "List facts"]}, {"q": "The Pilgrim's Progress is an:", "options": ["Essay on language", "Allegory", "Epic in Old English", "Newspaper"]}, {"q": "Romantic poets valued:", "options": ["War", "Strict law", "Only reason", "Emotion, imagination and nature"]}, {"q": "A dramatic monologue reveals:", "options": ["The page count", "The speaker's character", "The author's age", "The publisher"]}, {"q": "Modernist writers often used:", "options": ["Fragmentation and free verse", "Strict rhyme only", "No images", "Latin only"]}, {"q": "Things Fall Apart was written by:", "options": ["Chinua Achebe", "John Milton", "Mary Shelley", "George Orwell"]}, {"q": "A synthesis essay:", "options": ["Avoids a thesis", "Combines ideas from several sources into your own point", "Copies one article", "Lists quotes only"]}, {"q": "A strong personal narrative begins with:", "options": ["A specific scene", "A general statement", "A list of grades", "A dictionary definition"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: English 4$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,3,1,1,1,2,1,3,1,0,0,1,0}'::int[], array[$j$Beowulf is an Old English epic poem.$j$,$j$Pilgrims tell stories on the road to Canterbury.$j$,$j$Only Good Deeds goes with Everyman.$j$,$j$The last two lines are a couplet.$j$,$j$Five iambs make ten syllables.$j$,$j$The tragic hero is noble but flawed.$j$,$j$It was published in 1611.$j$,$j$Swift is a master of satire.$j$,$j$Characters and places stand for ideas.$j$,$j$Romanticism emphasized feeling and nature.$j$,$j$Browning's duke reveals himself.$j$,$j$They broke from traditional forms.$j$,$j$Achebe published it in 1958.$j$,$j$Synthesis builds a new, supported claim.$j$,$j$A scene hooks the reader.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: English 4$j$ on conflict (item_id) do nothing;
end
$seed$;
